<?php
require '../config/database.php';$adminPage=true;$pageTitle='Company Job Publishing';
if($_SERVER['REQUEST_METHOD']==='POST'){
    $action=$_POST['action']??'';
    if($action==='delete_job'){
        $jobId=(int)($_POST['job_id']??0);
        if($jobId>0){
            $check=$conn->prepare('SELECT COUNT(*) AS total FROM applications WHERE job_id=?');
            $check->bind_param('i',$jobId);$check->execute();
            $applicationCount=(int)$check->get_result()->fetch_assoc()['total'];
            if($applicationCount>0){header('Location: jobs.php?error=job_has_applications');exit;}
            $stmt=$conn->prepare('DELETE FROM jobs WHERE job_id=?');
            $stmt->bind_param('i',$jobId);$stmt->execute();
            header('Location: jobs.php?deleted=job');exit;
        }
    }
    if($action==='category'){$name=trim($_POST['category_name']??'');$description=trim($_POST['category_description']??'');if($name){$stmt=$conn->prepare('INSERT INTO categories(category_name,category_description) VALUES(?,?)');$stmt->bind_param('ss',$name,$description);$stmt->execute();header('Location: jobs.php?saved=category');exit;}}
    if($action==='job'){$company=trim($_POST['company_name']??'');$category=(int)($_POST['category_id']??0);$title=trim($_POST['title']??'');$description=trim($_POST['description']??'');$location=trim($_POST['location']??'');$requirements=trim($_POST['requirements']??'');$salary=trim($_POST['salary']??'');$deadline=$_POST['deadline']??'';if($company&&$category&&$title&&$description&&$location&&$requirements&&$salary&&$deadline){$stmt=$conn->prepare('INSERT INTO jobs(category_id,company_name,title,description,location,requirements,salary,deadline) VALUES(?,?,?,?,?,?,?,?)');$stmt->bind_param('isssssss',$category,$company,$title,$description,$location,$requirements,$salary,$deadline);$stmt->execute();header('Location: jobs.php?saved=job');exit;}}
}
$categories=$conn->query('SELECT * FROM categories ORDER BY category_name');$categoryOptions=$conn->query('SELECT * FROM categories ORDER BY category_name');$jobs=$conn->query('SELECT j.*,c.category_name FROM jobs j JOIN categories c ON c.category_id=j.category_id ORDER BY j.job_id DESC');include '../includes/header.php';
?>
<section class="admin-hero compact"><div><small>COMPANY RECRUITMENT DESK</small><h1>Post a New Job</h1><p>Enter company and vacancy information to publish it in the JOB entity.</p></div><a class="back-dashboard" href="index.php">← Dashboard</a></section><?php if(isset($_GET['saved'])):?><div class="notice standalone">New <?=htmlspecialchars($_GET['saved'])?> added successfully.</div><?php endif;?><?php if(isset($_GET['deleted'])):?><div class="notice standalone">Job deleted successfully.</div><?php endif;?><?php if(($_GET['error']??'')==='job_has_applications'):?><div class="error standalone">This job cannot be deleted because candidates have already applied for it.</div><?php endif;?><div class="admin-grid"><form class="card" method="post"><input type="hidden" name="action" value="job"><h1>Company Job Form</h1><div class="grid"><label class="full">Company Name<input name="company_name" placeholder="e.g. ABC Technologies Ltd." required></label><label>Job Title<input name="title" required></label><label>Category<select name="category_id" required><option value="">Choose category</option><?php while($c=$categoryOptions->fetch_assoc()):?><option value="<?=$c['category_id']?>"><?=htmlspecialchars($c['category_name'])?></option><?php endwhile;?></select></label><label>Location<input name="location" required></label><label>Salary<input name="salary" required></label><label class="full">Job Description<textarea name="description" rows="4" required></textarea></label><label class="full">Requirements<textarea name="requirements" rows="4" required></textarea></label><label>Application Deadline<input type="date" name="deadline" required></label></div><button class="submit">Publish New Job →</button></form><form class="card category-form" method="post"><input type="hidden" name="action" value="category"><h1>Add Category</h1><div class="grid"><label class="full">Category Name<input name="category_name" required></label><label class="full">Description<textarea name="category_description" rows="4"></textarea></label></div><button class="submit">Save Category</button><div class="category-cloud"><?php while($c=$categories->fetch_assoc()):?><span><?=htmlspecialchars($c['category_name'])?></span><?php endwhile;?></div></form></div><section class="card jobs-admin-list"><h1>Company Job List</h1><div class="table-wrap"><table><tr><th>ID</th><th>Company</th><th>Job</th><th>Category</th><th>Location</th><th>Deadline</th><th>Action</th></tr><?php while($j=$jobs->fetch_assoc()):?><tr><td>#<?=$j['job_id']?></td><td><strong><?=htmlspecialchars($j['company_name'])?></strong></td><td><?=htmlspecialchars($j['title'])?></td><td><?=htmlspecialchars($j['category_name'])?></td><td><?=htmlspecialchars($j['location'])?></td><td><?=$j['deadline']?></td><td><form class="delete-job-form" method="post" onsubmit="return confirm('Are you sure you want to delete this job?');"><input type="hidden" name="action" value="delete_job"><input type="hidden" name="job_id" value="<?=$j['job_id']?>"><button type="submit">Delete</button></form></td></tr><?php endwhile;?></table></div></section><?php include '../includes/footer.php';?>
